    a=ff(a,b,c,d,msg[i+0],7,-680876936);d=ff(d,a,b,c,msg[i+1],12,-389564586);c=ff(c,d,a,b,msg[i+2],17,606105819);b=ff(b,c,d,a,msg[i+3],22,-1044525330);
