document.getElementById('enc-html-btn').addEventListener('click', () =>
  runEncDec('enc-html-in', 'enc-html-out', 'enc-html-mode',
    v => v.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;'),
    v => v.replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#39;/g,"'")
  )
);

// JWT Decode (read-only — signing requires server-side for RS/ES algorithms)
document.getElementById('enc-jwt-btn').addEventListener('click', () => {
  const token = document.getElementById('enc-jwt-in').value.trim();
  const parts = token.split('.');
  if (parts.length < 2) { showToast('Invalid JWT — expected header.payload.signature', 'err'); return; }
  function b64urlDecode(s) {
    s = s.replace(/-/g,'+').replace(/_/g,'/');
    while (s.length % 4) s += '=';
    try { return JSON.stringify(JSON.parse(decodeURIComponent(escape(atob(s)))), null, 2); }
    catch { return atob(s); }
  }
  document.getElementById('enc-jwt-header').textContent  = b64urlDecode(parts[0]);
  document.getElementById('enc-jwt-payload').textContent = b64urlDecode(parts[1]);
  document.getElementById('enc-jwt-sig').textContent     = parts[2] || '(absent)';
  document.getElementById('enc-jwt-result').style.display = '';
});

