  function rotl(n,s){return(n<<s)|(n>>>(32-s));}
  function cmn(q,a,b,x,s,t){return safeAdd(rotl(safeAdd(safeAdd(a,q),safeAdd(x,t)),s),b);}
  const ff=(a,b,c,d,x,s,t)=>cmn((b&c)|(~b&d),a,b,x,s,t);
  const gg=(a,b,c,d,x,s,t)=>cmn((b&d)|(c&~d),a,b,x,s,t);
  const hh=(a,b,c,d,x,s,t)=>cmn(b^c^d,a,b,x,s,t);
  const ii=(a,b,c,d,x,s,t)=>cmn(c^(b|~d),a,b,x,s,t);
  str=unescape(encodeURIComponent(str));
  const msg=[]; let i;
  for(i=0;i<str.length;i++) msg[i>>2]|=(str.charCodeAt(i)&0xFF)<<((i%4)*8);
  const len8=str.length*8;
  msg[str.length>>2]|=0x80<<((str.length%4)*8);
  msg[(((str.length+64)>>6)<<4)+14]=len8;
  let a=1732584193,b=-271733879,c=-1732584194,d=271733878;
  for(i=0;i<msg.length;i+=16){
