    a=gg(a,b,c,d,msg[i+5],5,-701558691);d=gg(d,a,b,c,msg[i+10],9,38016083);c=gg(c,d,a,b,msg[i+15],14,-660478335);b=gg(b,c,d,a,msg[i+4],20,-405537848);
