    a=hh(a,b,c,d,msg[i+5],4,-378558);d=hh(d,a,b,c,msg[i+8],11,-2022574463);c=hh(c,d,a,b,msg[i+11],16,1839030562);b=hh(b,c,d,a,msg[i+14],23,-35309556);
