// Pure-JS SHA-224 (SHA-2 family, WebCrypto doesn't support SHA-224)
function sha224(message) {
  // SHA-224 initial hash values (first 32 bits of fractional parts of square roots of 9th-16th primes)
  let H = [0xc1059ed8,0x367cd507,0x3070dd17,0xf70e5939,0xffc00b31,0x68581511,0x64f98fa7,0xbefa4fa4];
  const K = [
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
  ];
  const rotr = (x,n) => ((x>>>n)|(x<<(32-n)))>>>0;
  const msg = new TextEncoder().encode(message);
  const len = msg.length;
  const bitlen = len * 8;
  const padlen = (len % 64 < 56) ? 56 - len%64 : 120 - len%64;
  const padded = new Uint8Array(len + padlen + 8);
  padded.set(msg); padded[len] = 0x80;
  const view = new DataView(padded.buffer);
  view.setUint32(padded.length-4, bitlen & 0xffffffff);
  view.setUint32(padded.length-8, Math.floor(bitlen/0x100000000));
  for (let i = 0; i < padded.length; i += 64) {
    const w = new Uint32Array(64);
    for (let j = 0; j < 16; j++) w[j] = view.getUint32(i+j*4);
    for (let j = 16; j < 64; j++) {
      const s0 = (rotr(w[j-15],7)^rotr(w[j-15],18)^(w[j-15]>>>3))>>>0;
      const s1 = (rotr(w[j-2],17)^rotr(w[j-2],19)^(w[j-2]>>>10))>>>0;
      w[j] = (w[j-16]+s0+w[j-7]+s1)>>>0;
    }
    let [a,b,c,d,e,f,g,h] = H;
    for (let j = 0; j < 64; j++) {
      const S1  = (rotr(e,6)^rotr(e,11)^rotr(e,25))>>>0;
      const ch  = ((e&f)^(~e&g))>>>0;
      const tmp1 = (h+S1+ch+K[j]+w[j])>>>0;
      const S0  = (rotr(a,2)^rotr(a,13)^rotr(a,22))>>>0;
      const maj = ((a&b)^(a&c)^(b&c))>>>0;
      const tmp2 = (S0+maj)>>>0;
      [h,g,f,e,d,c,b,a] = [g,f,e,(d+tmp1)>>>0,c,b,a,(tmp1+tmp2)>>>0];
    }
    H = H.map((hv,i)=>([a,b,c,d,e,f,g,h][i]+hv)>>>0);
  }
  return H.slice(0,7).map(n=>n.toString(16).padStart(8,'0')).join('');
}

// WebCrypto SHA (SHA-1, SHA-256, SHA-384, SHA-512)
async function sha(algorithm, text) {
  const buf = await crypto.subtle.digest(algorithm, new TextEncoder().encode(text));
  return Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, '0')).join('');
}

// Hash panel — debounced live update
const hashInput = document.getElementById('hash-input');
let _hashT = null;
hashInput.addEventListener('input', () => { clearTimeout(_hashT); _hashT = setTimeout(updateHashes, 200); });

async function updateHashes() {
  const text  = hashInput.value;
  const empty = !text;
  const set = (id, val) => {
    const el = document.getElementById(id);
    if (!el) return;
    el.textContent = val;
    el.className = 'hash-value' + (empty ? ' empty' : '');
  };
  set('hash-md5',    empty ? '—' : md5(text));
  set('hash-sha1',   empty ? '—' : await sha('SHA-1',   text));
  set('hash-sha224', empty ? '—' : sha224(text));           // pure-JS, no await needed
  set('hash-sha256', empty ? '—' : await sha('SHA-256', text));
  set('hash-sha384', empty ? '—' : await sha('SHA-384', text));
  set('hash-sha512', empty ? '—' : await sha('SHA-512', text));
}

// ── AES-256-GCM Encrypt / Decrypt ────────────────────────────────────────
async function deriveAESKey(passphrase) {
  const raw = await crypto.subtle.importKey('raw', new TextEncoder().encode(passphrase), 'PBKDF2', false, ['deriveKey']);
  return crypto.subtle.deriveKey(
    { name:'PBKDF2', salt:new TextEncoder().encode('lxcode-salt-v1'), iterations:100000, hash:'SHA-256' },
    raw, { name:'AES-GCM', length:256 }, false, ['encrypt','decrypt']
  );
}

document.getElementById('aes-enc-btn').addEventListener('click', async () => {
  const text = document.getElementById('aes-input').value;
  const pass = document.getElementById('aes-key').value;
  if (!text || !pass) { showToast('Text and passphrase required', 'warn'); return; }
  try {
    const key = await deriveAESKey(pass);
    const iv  = crypto.getRandomValues(new Uint8Array(12));
    const enc = await crypto.subtle.encrypt({ name:'AES-GCM', iv }, key, new TextEncoder().encode(text));
    const out = new Uint8Array(iv.length + enc.byteLength);
    out.set(iv); out.set(new Uint8Array(enc), iv.length);
    document.getElementById('aes-output').value = btoa(String.fromCharCode(...out));
    showToast('Encrypted', 'ok');
  } catch(e) { showToast('Encryption failed: ' + e.message, 'err'); }
});

document.getElementById('aes-dec-btn').addEventListener('click', async () => {
  const cipher = document.getElementById('aes-input').value.trim();
  const pass   = document.getElementById('aes-key').value;
  if (!cipher || !pass) { showToast('Ciphertext and passphrase required', 'warn'); return; }
  try {
    const raw = Uint8Array.from(atob(cipher), c => c.charCodeAt(0));
    const key = await deriveAESKey(pass);
    const dec = await crypto.subtle.decrypt({ name:'AES-GCM', iv:raw.slice(0,12) }, key, raw.slice(12));
    document.getElementById('aes-output').value = new TextDecoder().decode(dec);
    showToast('Decrypted', 'ok');
  } catch { showToast('Decryption failed — wrong passphrase?', 'err'); }
});

// ── HMAC-SHA256 Sign / Verify ─────────────────────────────────────────────
async function hmacKey(secret) {
  return crypto.subtle.importKey('raw', new TextEncoder().encode(secret), { name:'HMAC', hash:'SHA-256' }, false, ['sign','verify']);
}

document.getElementById('hmac-sign-btn').addEventListener('click', async () => {
  const msg = document.getElementById('hmac-input').value;
  const key = document.getElementById('hmac-key').value;
  if (!msg || !key) { showToast('Message and key required', 'warn'); return; }
  try {
    const k   = await hmacKey(key);
    const sig = await crypto.subtle.sign('HMAC', k, new TextEncoder().encode(msg));
    document.getElementById('hmac-output').value = Array.from(new Uint8Array(sig)).map(b=>b.toString(16).padStart(2,'0')).join('');
    showToast('Signed', 'ok');
  } catch(e) { showToast('Sign failed: '+e.message, 'err'); }
});

document.getElementById('hmac-verify-btn').addEventListener('click', async () => {
  const msg    = document.getElementById('hmac-input').value;
  const key    = document.getElementById('hmac-key').value;
  const sigHex = document.getElementById('hmac-output').value.trim();
  if (!msg || !key || !sigHex) { showToast('Message, key and signature required', 'warn'); return; }
  try {
    const sigBuf = Uint8Array.from((sigHex.match(/.{2}/g)||[]), b=>parseInt(b,16));
    const k      = await hmacKey(key);
    const valid  = await crypto.subtle.verify('HMAC', k, sigBuf, new TextEncoder().encode(msg));
    showToast(valid ? '✓ Signature valid' : '✗ Signature invalid', valid ? 'ok' : 'err');
  } catch { showToast('Verify failed — invalid signature hex?', 'err'); }
});

// ── Universal copy (data-copy-from="elementId") ───────────────────────────
document.querySelectorAll('[data-copy-from]').forEach(btn => {
  btn.addEventListener('click', async () => {
    const el  = document.getElementById(btn.dataset.copyFrom);
    const val = el ? (el.value !== undefined ? el.value : el.textContent) : '';
    if (!val || val === '—') { showToast('Nothing to copy'); return; }
    showToast((await copyText(val)) ? 'Copied' : 'Copy failed', (await copyText(val)) ? 'ok' : 'err');
  });
});

// ── Keyboard shortcuts ─────────────────────────────────────────────────────
document.addEventListener('keydown', e => {
  const ctrl = e.ctrlKey || e.metaKey;
  if (ctrl && e.key === 'f') { e.preventDefault(); if (_mode === 'edit') editor.execCommand('find'); }
  if (ctrl && e.key === 'h') { e.preventDefault(); if (_mode === 'edit') editor.execCommand('replace'); }
});

// ── Init ───────────────────────────────────────────────────────────────────
window.addEventListener('load', () => {
  initTheme();
  const saved = localStorage.getItem(KEY);
  editor.setValue(saved || '', -1);
  updateStatus();
  editor.focus();
});

resultDisplay.newContent:
/* LxCode Studio — SSL Toolkit main.js */
'use strict';

const KEY = 'lxcode_ssl';

// ── Ace ───────────────────────────────────────────────────────────────────
const editor = initAce('ace-editor', 'text');

editor.session.on('change', () => {
  updateStatus();
  localStorage.setItem(KEY, editor.getValue());
});
editor.selection.on('changeCursor', () => {
  const c = editor.getCursorPosition();
  document.getElementById('s-cur').textContent = 'Ln ' + (c.row + 1) + ', Col ' + (c.column + 1);
});
editor.selection.on('changeSelection', updateStatus);

// ── Status bar ────────────────────────────────────────────────────────────
function updateStatus() {
  const v = editor.getValue();
  document.getElementById('s-chars').textContent = v.length.toLocaleString() + ' chars';
  document.getElementById('s-words').textContent = (v.trim() ? v.trim().split(/\s+/).length : 0).toLocaleString() + ' words';
  document.getElementById('s-lines').textContent = editor.session.getLength().toLocaleString() + ' lines';
  const sel = editor.session.getTextRange(editor.getSelectionRange());
  const selEl = document.getElementById('s-sel');
  selEl.textContent = sel.length ? sel.length + ' selected' : '';
  selEl.style.display = sel.length ? '' : 'none';
}

// ── Mode switcher ─────────────────────────────────────────────────────────
let _mode = 'edit';
function setMode(m) {
  _mode = m;
  const elMap = { edit: 'editor-mode', compare: 'compare-mode', crypto: 'crypto-mode' };
  Object.entries(elMap).forEach(([key, elId]) => {
    const el  = document.getElementById(elId);
    const tab = document.getElementById('tab-' + key);
    if (el)  el.style.display = (m === key) ? 'flex' : 'none';
    if (tab) tab.classList.toggle('active', m === key);
  });
  if (m === 'compare') runDiff();
  if (m === 'edit') setTimeout(() => editor.resize(), 50);
}

// ── Text transform tools ──────────────────────────────────────────────────
function applyTool(fn, msg) {
  editor.setValue(fn(editor.getValue()), -1);
  updateStatus();
  localStorage.setItem(KEY, editor.getValue());
  if (msg) showToast(msg, 'ok');
}

document.getElementById('btn-upper').onclick      = () => applyTool(v => v.toUpperCase(), 'Upper case');
document.getElementById('btn-lower').onclick      = () => applyTool(v => v.toLowerCase(), 'Lower case');
document.getElementById('btn-title').onclick      = () => applyTool(v => v.replace(/\b\w/g, c => c.toUpperCase()), 'Title case');
document.getElementById('btn-trim').onclick       = () => applyTool(v => v.split('\n').map(l => l.trim()).join('\n').trim(), 'Trimmed');
document.getElementById('btn-sort-lines').onclick = () => applyTool(v => v.split('\n').sort().join('\n'), 'Sorted A→Z');
document.getElementById('btn-reverse').onclick    = () => applyTool(v => v.split('\n').reverse().join('\n'), 'Reversed');
document.getElementById('btn-dedup').onclick      = () => {
  const lines = editor.getValue().split('\n');
  const unique = [...new Set(lines)];
  applyTool(() => unique.join('\n'), 'Removed ' + (lines.length - unique.length) + ' duplicates');
};
document.getElementById('btn-b64e').onclick  = () => { try { applyTool(v => btoa(unescape(encodeURIComponent(v))), 'Base64 encoded'); } catch { showToast('Encode failed', 'err'); } };
document.getElementById('btn-b64d').onclick  = () => { try { applyTool(v => decodeURIComponent(escape(atob(v.trim()))), 'Base64 decoded'); } catch { showToast('Invalid Base64', 'err'); } };
document.getElementById('btn-urle').onclick  = () => applyTool(v => encodeURIComponent(v), 'URL encoded');
document.getElementById('btn-urld').onclick  = () => { try { applyTool(v => decodeURIComponent(v), 'URL decoded'); } catch { showToast('Invalid URL encoding', 'err'); } };
document.getElementById('btn-htmle').onclick = () => applyTool(v => v.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'), 'HTML encoded');
document.getElementById('btn-htmld').onclick = () => applyTool(v => v.replace(/&quot;/g,'"').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&amp;/g,'&'), 'HTML decoded');

// ── File ops ──────────────────────────────────────────────────────────────
document.getElementById('btn-sample').onclick = () => {
  editor.setValue('Hello, World!\n\nThis is LxCode Studio — Text Viewer.\nEdit, transform, encode, or compare text here.\n\nLine 5\nLine 6\nLine 7', -1);
  showToast('Sample loaded');
};
document.getElementById('btn-import').onclick = () =>
  importFile('.txt,.md,.csv,.log,.json', (c, n) => { editor.setValue(c, -1); showToast('Imported: ' + n, 'ok'); });
document.getElementById('btn-export').onclick = () => {
  if (!editor.getValue().trim()) { showToast('Nothing to export'); return; }
  exportFile(editor.getValue(), 'export.txt', 'text/plain');
  showToast('Exported as export.txt', 'ok');
};
document.getElementById('btn-copy').onclick = async () => {
  const ok = await copyText(editor.getValue());
  showToast(ok ? 'Copied' : 'Copy failed', ok ? 'ok' : 'err');
};
document.getElementById('btn-clear').onclick = () => {
  if (!editor.getValue() || !confirm('Clear editor?')) return;
  editor.setValue('', -1); showToast('Cleared');
};
document.getElementById('btn-find').onclick         = () => editor.execCommand('find');
document.getElementById('btn-replace-open').onclick = () => editor.execCommand('replace');

// ── Compare / Diff ────────────────────────────────────────────────────────
const cmpA          = document.getElementById('cmp-a');
const cmpB          = document.getElementById('cmp-b');
const diffOutput    = document.getElementById('diff-output');
const diffSummary   = document.getElementById('diff-summary');
const compareResult = document.getElementById('compare-result');

let _diffT = null;
[cmpA, cmpB].forEach(el => el.addEventListener('input', () => { clearTimeout(_diffT); _diffT = setTimeout(runDiff, 400); }));

document.getElementById('btn-run-diff').onclick = runDiff;
document.getElementById('btn-swap').onclick = () => { const t = cmpA.value; cmpA.value = cmpB.value; cmpB.value = t; runDiff(); };
document.getElementById('btn-copy-from-editor').onclick = () => { cmpA.value = editor.getValue(); runDiff(); showToast('Editor → A', 'ok'); };
document.getElementById('btn-clear-compare').onclick = () => {
  cmpA.value = ''; cmpB.value = '';
  compareResult.style.display = 'none';
  diffOutput.innerHTML = ''; diffSummary.innerHTML = '';
};

function runDiff() {
  if (!cmpA.value && !cmpB.value) { compareResult.style.display = 'none'; return; }
  compareResult.style.display = 'block';
  const linesA = cmpA.value.split('\n'), linesB = cmpB.value.split('\n');
  const diff = computeDiff(linesA, linesB);
  let adds = 0, dels = 0;
  diffOutput.innerHTML = '';
  diff.forEach(([type, lineA, lineB]) => {
    const row = document.createElement('div'); row.className = 'diff-line ' + type;
    const ln  = document.createElement('div'); ln.className = 'diff-ln';
    ln.textContent = type === 'add' ? '+' + lineB : type === 'del' ? '-' + lineA : lineA;
    const text = document.createElement('div'); text.className = 'diff-text';
    text.textContent = type === 'add' ? linesB[lineB - 1] : linesA[lineA - 1];
    row.appendChild(ln); row.appendChild(text); diffOutput.appendChild(row);
    if (type === 'add') adds++; if (type === 'del') dels++;
  });
  diffSummary.innerHTML =
    `<div class="diff-stat"><span class="dot dot-add"></span><span>${adds} addition${adds !== 1 ? 's' : ''}</span></div>` +
    `<div class="diff-stat"><span class="dot dot-del"></span><span>${dels} deletion${dels !== 1 ? 's' : ''}</span></div>` +
    `<div class="diff-stat" style="color:var(--muted)">${diff.length - adds - dels} unchanged</div>`;
}

function computeDiff(a, b) {
  const n = a.length, m = b.length;
  const dp = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0));
  for (let i = n - 1; i >= 0; i--)
    for (let j = m - 1; j >= 0; j--)
      dp[i][j] = a[i] === b[j] ? dp[i+1][j+1] + 1 : Math.max(dp[i+1][j], dp[i][j+1]);
  const result = []; let i = 0, j = 0;
  while (i < n || j < m) {
    if (i < n && j < m && a[i] === b[j]) { result.push(['eq', i+1, j+1]); i++; j++; }
    else if (j < m && (i >= n || dp[i][j+1] >= dp[i+1][j])) { result.push(['add', i+1, j+1]); j++; }
    else { result.push(['del', i+1, j+1]); i++; }
  }
  return result;
}

